#!/usr/bin/env node
'use strict';
const fs=require('fs'),path=require('path'),crypto=require('crypto');
const HERE=__dirname,M=require('./model.js'),R=M.R,B=M.BASE,OUT=path.join(HERE,'controls.json');
function assert(x,m){if(!x)throw Error(m);} function sha(b){return crypto.createHash('sha256').update(b).digest('hex');} function fsha(p){return sha(fs.readFileSync(p));} function stable(x){return JSON.stringify(x,null,2)+'\n';}
function rawForOriented(hex,orientation){const pairs=hex.match(/../g);if(orientation==='forward')return {hex,tokens:[hex.slice(0,2),...Array.from({length:218},(_,i)=>hex.slice(2+5*i,7+5*i))]};if(orientation==='full_hex_reverse')return rawForOriented([...hex].reverse().join(''),'forward');if(orientation==='byte_pair_reverse')return rawForOriented(pairs.slice().reverse().join(''),'forward');if(orientation==='nibble_swap')return rawForOriented(pairs.map(x=>x[1]+x[0]).join(''),'forward');if(orientation==='visible_token_reverse'){const lens=[...Array(218).fill(5),2],ts=[];let n=0;for(const l of lens){ts.push(hex.slice(n,n+l));n+=l;}const raw=ts.reverse();return {hex:raw.join(''),tokens:raw};}throw Error('orientation');}
function geometry(){const tables=[],seen=new Set();for(const t of M.transforms()){const vals=[],inv=[];for(let x=0;x<256;x++){const y=M.transformByte(x,t.reflect,t.k);vals.push(y);inv.push(M.inverseByte(y,t.reflect,t.k));assert(inv[x]===x,'inverse');}assert(new Set(vals).size===256,'bijection');const h=sha(Buffer.from(vals));assert(!seen.has(h),'distinct transforms');seen.add(h);tables.push({...t,table_sha256:h});}assert(M.transformByte(0xab,false,4)===0xba,'nibble swap');return {transforms:tables,nibble_swap_transform:'rotate:4',identity_transform:'rotate:0'};}
function fixtureHex(){return Buffer.from(Array.from({length:546},(_,i)=>(i*73+19)&255)).toString('hex').toUpperCase();}
function dedupControl(){const raw=rawForOriented(fixtureHex(),'forward'),o=B.orientations(raw.hex,raw.tokens),g=M.deduplicate(o),aliases=g.flatMap(x=>x.aliases.map(a=>[a.orientation,a.transform].join('|')));assert(aliases.length===80&&new Set(aliases).size===80,'alias coverage');const forwardIdentity=g.find(x=>x.aliases.some(a=>a.orientation==='forward'&&a.transform==='rotate:0'));assert(forwardIdentity.aliases.some(a=>a.orientation==='nibble_swap'&&a.transform==='rotate:4'),'nibble alias');return {logical_inputs:80,unique_inputs:g.length,alias_histogram:Object.fromEntries([...new Set(g.map(x=>x.aliases.length))].sort((a,b)=>a-b).map(n=>[n,g.filter(x=>x.aliases.length===n).length])),groups:g.map(x=>({input_sha256:x.input_sha256,aliases:x.aliases}))};}
async function compute(){R.verifySources();const ctx=await R.load(),pt=Buffer.from(('THIS IS A SYNTHETIC UPPERCASE ENGLISH CONTROL WITH NUMBERS 12345 AND PUNCTUATION. ').repeat(9).slice(0,546),'ascii');assert(pt.length===546,'plant len');const c=B.contexts().find(x=>x.cipher==='twofish'&&x.mode==='cfb8'&&x.key==='Zombies'&&x.iv==='ascii0');assert(c,'context');const ct=R.encrypt(ctx,c.cipher,c.key,c.iv,pt,c.mode),plant=[];for(const orientation of B.ORIENTATIONS){const pre=M.inverse(ct,true,3),raw=rawForOriented(pre.toString('hex').toUpperCase(),orientation),or=B.orientations(raw.hex,raw.tokens);assert(Buffer.from(or[orientation],'hex').equals(pre),'orientation inverse');const got=R.decrypt(ctx,c.cipher,c.key,c.iv,M.transform(Buffer.from(or[orientation],'hex'),true,3),c.mode);assert(got.equals(pt),'pipeline plant');const s=M.screen(got,c);assert(s.ascii.full.hit&&s.ascii.tail.hit,'ascii screen');plant.push({orientation,raw_hex_sha256:sha(Buffer.from(raw.hex)),oriented_sha256:sha(pre),ciphertext_sha256:sha(ct),plaintext_sha256:sha(got),flags:s.flagged_windows});}
 const pins={};for(const f of ['model.js','controls.js'])pins[f]=fsha(path.join(HERE,f));for(const f of ['runtime.js','model.js','controls.js','controls.json'])pins['../first_layer_occupancy/'+f]=fsha(path.resolve(HERE,'../first_layer_occupancy',f));for(const [f,h] of Object.entries(R.PINS))pins[path.relative(HERE,f)]=h;
 return {identity:'ASTRA',status:'synthetic controls complete',target_evaluated:false,scope:{transforms:16,orientations:B.ORIENTATIONS,logical_inputs:80,contexts_per_unique_input:312,ascii_rule:'TAB LF CR or ASCII 32..126; ratio >= 0.75',occupancy:'accepted frozen first_layer_occupancy full and one-block-skipped screen'},source_pins:pins,geometry:geometry(),dedup:dedupControl(),plant:{cipher_context:c,transform:'reflect:3',rows:plant}};}
async function main(){let gen=null;if(process.argv.length===4&&process.argv[2]==='--generate')gen=path.resolve(process.argv[3]);else if(process.argv.length!==2)throw Error('usage: node controls.js [--generate NEW_PATH]');const got=await compute();if(gen){if(fs.existsSync(gen))throw Error('refuse existing');fs.writeFileSync(gen,stable(got));console.log(JSON.stringify({status:'generated',path:gen,sha256:fsha(gen)}));}else{assert(fs.existsSync(OUT),'missing controls ledger');assert(stable(got)===stable(JSON.parse(fs.readFileSync(OUT,'utf8'))),'ledger mismatch');console.log(JSON.stringify({identity:'ASTRA',status:'PASS',ledger_sha256:fsha(OUT),unique_inputs:got.dedup.unique_inputs}));}}
main().catch(e=>{console.error(e.stack||String(e));process.exitCode=1;});
